const item = $input.first().json;
const q = item.query ?? item.params ?? {};
return [{
  json: {
    ...item,
    hubMode: String(q['hub.mode'] ?? item['hub.mode'] ?? ''),
    hubVerifyToken: String(q['hub.verify_token'] ?? item['hub.verify_token'] ?? ''),
    hubChallenge: String(q['hub.challenge'] ?? item['hub.challenge'] ?? ''),
  },
}];

const body = $input.first().json.body ?? $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.lastPageReplyAt) staticData.lastPageReplyAt = {};

const collected = [];
let recordedEcho = false;

for (const entry of body.entry || []) {
  for (const messaging of entry.messaging || []) {
    // Page/human outbound messages arrive as echoes — track for pre-send skip
    if (messaging.message?.is_echo) {
      const userId = messaging.recipient?.id;
      const ts = Number(messaging.timestamp) || Date.now();
      if (userId) {
        const prev = Number(staticData.lastPageReplyAt[userId] || 0);
        if (ts >= prev) staticData.lastPageReplyAt[userId] = ts;
        recordedEcho = true;
      }
      continue;
    }
    const text = messaging.message?.text?.trim();
    if (!text) continue;
    collected.push({
      senderId: messaging.sender?.id,
      messageId: messaging.message?.mid,
      text,
      timestamp: messaging.timestamp,
    });
  }
}

if (!collected.length) {
  return [{
    json: {
      skip: true,
      reason: recordedEcho ? 'page_echo' : 'no_messaging_event',
    },
  }];
}

const senderId = collected[0].senderId;
return [{
  json: {
    skip: false,
    senderId,
    messageId: collected.map((m) => m.messageId).filter(Boolean).join(','),
    text: collected.map((m) => m.text).join('\n'),
    timestamp: collected[0].timestamp,
    inboundMessages: collected,
  },
}];

const item = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.pending) staticData.pending = {};
if (!staticData.processedMessages) staticData.processedMessages = {};
if (!staticData.busy) staticData.busy = {};
if (!staticData.conversations) staticData.conversations = {};

const now = Date.now();
for (const [mid, ts] of Object.entries(staticData.processedMessages)) {
  if (now - Number(ts) > 3600000) delete staticData.processedMessages[mid];
}

const inbound = Array.isArray(item.inboundMessages) && item.inboundMessages.length
  ? item.inboundMessages
  : [{ senderId: item.senderId, messageId: item.messageId, text: item.text, timestamp: item.timestamp }];

const fresh = [];
for (const msg of inbound) {
  const mid = msg.messageId;
  if (mid && staticData.processedMessages[mid]) continue;
  if (mid) staticData.processedMessages[mid] = now;
  fresh.push(msg);
}

if (!fresh.length) {
  return [{ json: { ...item, skip: true, ready: false, reason: 'duplicate' } }];
}

const senderId = String(fresh[0].senderId || item.senderId);
if (!staticData.pending[senderId]) {
  staticData.pending[senderId] = { messages: [], generation: 0 };
}

for (const msg of fresh) {
  staticData.pending[senderId].messages.push({
    text: msg.text,
    messageId: msg.messageId,
    timestamp: msg.timestamp,
  });
}
staticData.pending[senderId].generation += 1;
const myGeneration = staticData.pending[senderId].generation;

return [{
  json: {
    senderId,
    messageId: fresh.map((m) => m.messageId).filter(Boolean).join(','),
    text: fresh.map((m) => m.text).join('\n'),
    timestamp: fresh[0].timestamp,
    myGeneration,
    skip: false,
    ready: false,
  },
}];

const input = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.pending) staticData.pending = {};
if (!staticData.busy) staticData.busy = {};

const senderId = String(input.senderId);
const pending = staticData.pending[senderId];
const myGeneration = input.myGeneration;

if (!pending || pending.generation !== myGeneration) {
  return [{ json: { ...input, skip: true, ready: false, reason: 'superseded' } }];
}

if (staticData.busy[senderId]) {
  return [{ json: { ...input, skip: false, ready: false, reason: 'busy' } }];
}

if (!pending.messages.length) {
  return [{ json: { ...input, skip: true, ready: false, reason: 'empty' } }];
}

const batch = pending.messages.slice();
pending.messages = [];
staticData.busy[senderId] = true;

const combinedText = batch.map((m) => m.text).join('\n');
return [{
  json: {
    senderId,
    messageId: batch.map((m) => m.messageId).filter(Boolean).join(','),
    text: combinedText,
    timestamp: batch[0].timestamp,
    myGeneration,
    accumulatedCount: batch.length,
    skip: false,
    ready: true,
    reason: 'claimed',
  },
}];

function collectFaqs() {
  const rows = $('Extract FAQ').all().map((row) => row.json);
  const faqs = [];
  for (const row of rows) {
    if (row.question && row.answer) {
      faqs.push({ question: row.question, answer: row.answer });
      continue;
    }
    if (Array.isArray(row.data)) {
      for (const entry of row.data) {
        if (entry?.question && entry?.answer) faqs.push(entry);
      }
      continue;
    }
    if (row.data?.question && row.data?.answer) {
      faqs.push({ question: row.data.question, answer: row.data.answer });
    }
  }
  if (!faqs.length) {
    throw new Error('No FAQ items — deploy knowledge/faq-items.json and check Extract FAQ output');
  }
  return faqs;
}

const item = $('Claim Burst').item.json;
const faqs = collectFaqs();
const textLower = (item.text || '').toLowerCase();

function detectUserLanguage(text) {
  return /[\u0980-\u09FF]/.test(text) ? 'bangla' : 'english';
}

const userLanguage = detectUserLanguage(item.text || '');

const escalationTopics = [
  'refund',
  'payment dispute',
  'account locked',
  'password reset',
  'bug report',
  'data deletion',
  'billing issue',
  'রিফান্ড',
  'ফেরত',
  'পেমেন্ট',
  'বিলিং',
];
const escalationReplyEn = 'Thanks for reaching out. This needs help from our support team — please call +8801814266295 with your account details, and we\'ll follow up shortly.';
const escalationReplyBn = 'আপনার বার্তার জন্য ধন্যবাদ। এই বিষয়টি সাপোর্ট টিমের সহায়তা দরকার — অনুগ্রহ করে +8801814266295 নম্বরে কল করুন, আমরা শীঘ্রই যোগাযোগ করব।';
const escalationReply = userLanguage === 'bangla' ? escalationReplyBn : escalationReplyEn;
const needsEscalation = escalationTopics.some((topic) => {
  if (/[\u0980-\u09FF]/.test(topic)) return (item.text || '').includes(topic);
  return textLower.includes(topic.toLowerCase());
});

if (needsEscalation) {
  return [{
    json: {
      ...item,
      userLanguage,
      needsEscalation: true,
      replyText: escalationReply,
      skipLlm: true,
      skip: false,
    },
  }];
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.conversations) staticData.conversations = {};

const history = staticData.conversations[item.senderId] || [];
const faqBlock = faqs
  .map((f) => `Q: ${f.question}\nA: ${f.answer}`)
  .join('\n\n');

const org = {
  name: 'Promise School',
  website: $env.SITE_URL || 'https://www.promiseschool.app',
  supportEmail: $env.SUPPORT_EMAIL || 'support@promiseschool.com',
  hobbycampUrl: $env.HOBBYCAMP_URL || 'https://www.promiseschool.app/hobbycamp',
};
const languageRule = userLanguage === 'bangla'
  ? '- CRITICAL LANGUAGE: The user wrote in Bangla (Bengali). Reply ONLY in natural, meaningful Bangla sentences. Keep URLs, phone numbers, and course prices (৳) in Latin/Arabic numerals. Do not reply in English except for proper nouns already in Latin script.'
  : '- CRITICAL LANGUAGE: The user wrote in English. Reply ONLY in clear, meaningful English sentences. Do not use Bangla script.';

const multiNote = (item.accumulatedCount || 1) > 1
  ? `- The user sent ${item.accumulatedCount} messages in a short burst. Answer ALL of them in ONE reply.`
  : '- Reply once to the user message.';

const systemPrompt = [
  "You are Promise School's friendly support assistant on Facebook Messenger.",
  'Rules:',
  '- Answer ONLY using the FAQ/knowledge below. If unsure or they need updates/support, tell them to call +8801814266295 — never share support@promiseschool.com or ask them to email.',
  '- Do not invent prices, dates, courses, or features.',
  languageRule,
  multiNote,
  '- Write like a helpful human: short warm paragraphs, not bullet walls unless listing steps.',
  '- Max 3-4 sentences unless they ask for detail.',
  '- For Hobbycamp enrollment or payment, share ' + (org.hobbycampUrl || 'https://www.promiseschool.app/hobbycamp') + ' and say they can call +8801814266295 for help.',
  '- Write complete meaningful sentences (not fragments or keyword dumps). When listing courses, use short readable lines with price, start date, and mode.',
  '- Match the user language strictly: Bangla question → Bangla answer; English question → English answer.',
  '',
  'KNOWLEDGE:',
  faqBlock || '(No FAQ entries loaded)',
  '',
  'Organization: ' + (org.name || 'Promise School') + ' — ' + (org.website || 'https://promiseschool.com'),
].join('\n');

const messages = [{ role: 'system', content: systemPrompt }];
for (const turn of history.slice(-8)) {
  messages.push({ role: turn.role, content: turn.content });
}
messages.push({
  role: 'user',
  content: (userLanguage === 'bangla' ? '[উত্তর শুধু বাংলায় দিন]\n' : '[Reply in English only]\n') + item.text,
});

return [{
  json: {
    ...item,
    userLanguage,
    needsEscalation: false,
    skipLlm: false,
    skip: false,
    ollamaMessages: messages,
    historyLength: history.length,
  },
}];

const prep = $('Prepare Prompt').item.json;
const ollama = $input.first().json;
const userLanguage = prep.userLanguage || (/[\u0980-\u09FF]/.test(prep.text || '') ? 'bangla' : 'english');
let replyText = ollama.message?.content?.trim() || '';

if (!replyText) {
  replyText = userLanguage === 'bangla'
    ? 'Promise School-এ মেসেজ করার জন্য ধন্যবাদ! আমাদের টিম শীঘ্রই উত্তর দেবে। কল করুন: +8801814266295 — Hobbycamp: https://www.promiseschool.app/hobbycamp'
    : 'Thanks for messaging Promise School! A team member will follow up soon. Call +8801814266295 — Hobbycamp: https://www.promiseschool.app/hobbycamp';
}

// Prefer phone over support email in any model output
replyText = replyText.replace(/support@promiseschool\.com/gi, '+8801814266295');
replyText = replyText.replace(/(?:ইমেইল|মেসেজ)\s*করুন\s*:?\s*\+8801814266295/g, 'কল করুন: +8801814266295');
replyText = replyText.replace(/(?:email|message|msg)\s*(?:us\s+)?(?:at\s+)?\+8801814266295/gi, 'call +8801814266295');
replyText = replyText.replace(/please\s+email\s+\+8801814266295/gi, 'please call +8801814266295');

const unsurePatterns = [
  "i don't know",
  "i do not know",
  "not sure",
  "cannot find",
  "can't find",
  "unable to answer",
  'জানি না',
  'নিশ্চিত নই',
  'উত্তর দিতে পারছি না',
];

const lower = replyText.toLowerCase();
if (unsurePatterns.some((p) => lower.includes(p) || replyText.includes(p))) {
  replyText = userLanguage === 'bangla'
    ? 'এ বিষয়ে আমি পুরোপুরি নিশ্চিত নই — অনুগ্রহ করে +8801814266295 নম্বরে কল করুন, আমাদের টিম সরাসরি সাহায্য করবে।'
    : "I'm not fully sure about that one — please call +8801814266295 and our team will help you directly.";
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.conversations) staticData.conversations = {};
if (!staticData.conversations[prep.senderId]) staticData.conversations[prep.senderId] = [];

staticData.conversations[prep.senderId].push(
  { role: 'user', content: prep.text },
  { role: 'assistant', content: replyText }
);

if (staticData.conversations[prep.senderId].length > 20) {
  staticData.conversations[prep.senderId] = staticData.conversations[prep.senderId].slice(-20);
}

return [{
  json: {
    senderId: prep.senderId,
    replyText,
    needsEscalation: prep.needsEscalation || false,
    userText: prep.text,
  },
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.lastPageReplyAt) staticData.lastPageReplyAt = {};

let prep = {};
try {
  prep = $('Prepare Prompt').item.json;
} catch (e) {
  prep = $input.first().json;
}

const senderId = String(prep.senderId || '');
let claimTs = Number(prep.timestamp) || 0;
try {
  const claim = $('Claim Burst').item.json;
  if (claim?.timestamp) claimTs = Number(claim.timestamp) || claimTs;
} catch (e) { /* ignore */ }

const pageId = String($env.META_PAGE_ID || '');
const graph = $input.first().json;

let pageRepliedAfter = false;
let graphChecked = false;
let graphError = false;

try {
  const conversations = graph?.data;
  if (Array.isArray(conversations)) {
    graphChecked = true;
    const messages = conversations[0]?.messages?.data || [];
    for (const msg of messages) {
      const fromId = String(msg.from?.id || '');
      const created = msg.created_time ? Date.parse(msg.created_time) : 0;
      // Page-originated message after the customer burst ⇒ human (or other Page sender) already answered
      if (pageId && fromId === pageId && created > claimTs) {
        pageRepliedAfter = true;
        break;
      }
      // Fallback without page id: any non-user sender after claim
      if (!pageId && fromId && fromId !== senderId && created > claimTs) {
        pageRepliedAfter = true;
        break;
      }
    }
  } else if (graph?.error || graph?.message) {
    graphError = true;
  }
} catch (e) {
  graphError = true;
}

const echoTs = Number(staticData.lastPageReplyAt[senderId] || 0);
const echoRepliedAfter = echoTs > claimTs;

const skipSend = pageRepliedAfter || echoRepliedAfter;

// Roll back conversation memory added in Finalize / escalation path when we skip send
if (skipSend && senderId && Array.isArray(staticData.conversations?.[senderId])) {
  const hist = staticData.conversations[senderId];
  if (hist.length >= 2) {
    const last = hist[hist.length - 1];
    const prev = hist[hist.length - 2];
    if (last?.role === 'assistant' && prev?.role === 'user') {
      staticData.conversations[senderId] = hist.slice(0, -2);
    }
  }
}

return [{
  json: {
    senderId,
    claimTs,
    skipSend,
    pageRepliedAfter,
    echoRepliedAfter,
    graphChecked,
    graphError,
    replyText: prep.replyText || undefined,
  },
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.busy) staticData.busy = {};

let senderId = '';
try {
  senderId = String($('Prepare Prompt').item.json.senderId || '');
} catch (e) {
  senderId = String($input.first().json.senderId || '');
}

if (senderId) {
  staticData.busy[senderId] = false;
}

const pendingLeft = (staticData.pending && staticData.pending[senderId] && staticData.pending[senderId].messages)
  ? staticData.pending[senderId].messages.length
  : 0;

return [{
  json: {
    senderId,
    busyReleased: true,
    pendingLeft,
  },
}];
